#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factArr, invFactArr;

long long addMod(long long a, long long b) {
    return (a + b) % MOD;
}

long long subMod(long long a, long long b) {
    return ((a - b) % MOD + MOD) % MOD;
}

long long mulMod(long long a, long long b) {
    return (a * b) % MOD;
}

long long fastPow(long long base, long long exp) {
    if (exp == 0) return 1;
    long long half = fastPow(base, exp / 2);
    if (exp % 2 == 0) return mulMod(half, half);
    return mulMod(half, mulMod(half, base));
}

void initializeFactorials() {
    factArr.resize(1000000);
    invFactArr.resize(1000000);
    factArr[0] = 1;
    for (int i = 1; i < (int)factArr.size(); i++) {
        factArr[i] = mulMod(factArr[i - 1], i);
    }
    invFactArr.back() = fastPow(factArr.back(), MOD - 2);
    for (int i = (int)invFactArr.size() - 2; i >= 0; i--) {
        invFactArr[i] = mulMod(invFactArr[i + 1], i + 1);
    }
}

long long calculateCombination(int n, int k) {
    return mulMod(factArr[n], mulMod(invFactArr[k], invFactArr[n - k]));
}

long long calculatePower(int base, long long exp) {
    long long total = 0;
    for (int i = 0; i < base; i++) {
        long long term = mulMod(fastPow(base - i, exp), calculateCombination(base, i));
        if (i % 2 == 0) {
            total = addMod(total, term);
        } else {
            total = subMod(total, term);
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    initializeFactorials();

    int totalN, totalK;
    cin >> totalN >> totalK;

    if (totalK == 0) {
        cout << factArr[totalN] << "\n";
        return 0;
    }
    if (totalK >= totalN) {
        cout << 0 << "\n";
        return 0;
    }

    int remaining = totalN - totalK;
    long long assignWays = calculatePower(remaining, totalN);
    long long pickWays = calculateCombination(totalN, remaining);
    long long result = mulMod(assignWays, pickWays);
    cout << mulMod(result, 2) << "\n";

    return 0;
}

